package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.cards.Card;import mage.constants.*;import mage.game.permanent.*;import mage.game.permanent.token.GoblinToken;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
public final class FourthSeatRecoveredCombatTest {
 public static void main(String[]args)throws Exception{
  for(boolean temple:new boolean[]{false,true})for(int blockers:new int[]{2,6})run("Gishath actual sourcewise prevention temple="+temple+" sources="+blockers,()->{FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();Permanent g=f.board("g.GishathSunsAvatar","Gishath, Sun's Avatar");f.identifyCommander(g.getId());if(temple)f.board("t.TempleAltisaur","Temple Altisaur").setTapped(true);List<Permanent> damage=new ArrayList<>();for(int seat=0;seat<3;seat++)for(int i=0;i<blockers;i++){Permanent b=f.enemyBoard(seat,"c.CentaurCourser","Centaur Courser");if(seat==0)damage.add(b);}f.combat();f.bot.selectAttackers(f.game,f.bot.getId());check(f.game.getCombat().getAttackers().contains(g.getId())==(temple&&blockers==2),"Wrong prevention attack decision");for(Permanent b:damage)g.damage(3,b.getId(),b.getAbilities().get(0),f.game,true,true);check(g.getDamage()==(temple?blockers:blockers*3),"Actual prevention differs from assumed model");});
  for(boolean removed:new boolean[]{false,true})run("Temple unavailable or prevention prohibited removed="+removed,()->{FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();Permanent g=f.board("g.GishathSunsAvatar","Gishath, Sun's Avatar"),temple=f.board("t.TempleAltisaur","Temple Altisaur");f.identifyCommander(g.getId());temple.setTapped(true);for(int seat=0;seat<3;seat++)for(int i=0;i<2;i++)f.enemyBoard(seat,"c.CentaurCourser","Centaur Courser");if(removed)temple.moveToZone(Zone.GRAVEYARD,null,f.game,false);else{Card crack=f.enemyHand("s.Skullcrack","Skullcrack");crack.getSpellAbility().getTargets().get(0).addTarget(f.bot.getId(),crack.getSpellAbility(),f.game);f.castEnemy(crack);resolve(f);f.game.getState().setActivePlayerId(f.bot.getId());}f.game.applyEffects();f.combat();f.bot.selectAttackers(f.game,f.bot.getId());check(!f.game.getCombat().getAttackers().contains(g.getId()),"Stale prevention assumed");});
  for(boolean killable:new boolean[]{false,true})run("Safe blocker attrition requires actually killable blocker="+killable,()->{FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();Permanent g=f.board("g.GishathSunsAvatar","Gishath, Sun's Avatar");f.identifyCommander(g.getId());for(int seat=0;seat<3;seat++)f.enemyBoard(seat,killable?"w.WallOfIce":"w.WallOfStone",killable?"Wall of Ice":"Wall of Stone");f.combat();f.bot.selectAttackers(f.game,f.bot.getId());check(f.game.getCombat().getAttackers().contains(g.getId())==killable,"Attrition attack boundary wrong");});
  for(String variant:new String[]{"ready","fresh-haste","fresh-sick","lethal-crackback"})run("Large real Goblin army intermediate subset "+variant,()->{FourthSeatRealGameTest.Fixture f=fixture("k.KrenkoMobBoss","Krenko, Mob Boss");f.bot.setLife(10,f.game,null);Permanent castle=f.board("c.CastleEmbereth","Castle Embereth");Ability source=castle.getAbilities(f.game).getActivatedAbilities(Zone.BATTLEFIELD).stream().filter(a->!a.isManaAbility()).findFirst().get();check(new GoblinToken().putOntoBattlefield(100,f.game,source,f.bot.getId()),"Real Goblin tokens not created");if(variant.equals("ready")||variant.equals("lethal-crackback"))for(Permanent p:f.game.getBattlefield().getAllActivePermanents(f.bot.getId()))if(p.isCreature(f.game))((PermanentToken)p).removeSummoningSickness();if(variant.equals("fresh-haste"))f.board("m.MassHysteria","Mass Hysteria");f.bot.getManaPool().addMana(Mana.RedMana(3),f.game,source);check(f.bot.activateAbility((ActivatedAbility)source,f.game),"Actual Castle boost failed");resolve(f);for(int i=0;i<32;i++)f.enemyBoard(0,"e.ElvishReclaimer","Elvish Reclaimer");f.enemyBoard(1,"b.BlazingArchon","Blazing Archon");f.enemyBoard(2,"b.BlazingArchon","Blazing Archon");for(int i=0;i<(variant.equals("lethal-crackback")?12:2);i++)f.enemyBoard(1,"g.Gigantosaurus","Gigantosaurus");f.combat();f.bot.selectAttackers(f.game,f.bot.getId());int n=f.game.getCombat().getAttackers().size();if(variant.equals("fresh-sick")||variant.equals("lethal-crackback"))check(n==0,"Illegal or lethal-crackback attack");else check(n>0&&n<100,"Search missed useful intermediate army or sent all defenders");for(UUID id:f.game.getCombat().getAttackers())check(f.game.getPermanent(id).getPower().getValue()==2,"Army boost fixture wrong");});
  finish("RECOVERED_COMBAT");
 }
}
